svg.script:
function setMuscle(id, active) {
  const el = document.getElementById(id);
  if (el) el.classList.toggle('active', !!active);
}

function toggleMuscle(id) {
  const el = document.getElementById(id);
  if (el) el.classList.toggle('active');
}

function highlightMuscles(ids) {
  document.querySelectorAll('.muscle').forEach(el => el.classList.remove('active'));
  (Array.isArray(ids) ? ids : [ids]).forEach(id => setMuscle(id, true));
}

function clearMuscles() {
  document.querySelectorAll('.muscle').forEach(el => el.classList.remove('active'));
}

